questionvariables.text:
/* one2one=1: fare rises steadily (one-to-one).
   one2one=0: fare has a flat zone, so a horizontal line meets it many times (many-to-one). */
one2one: rand([0, 1]);
ta1: [[onetoone, is(one2one=1), "one-to-one"], [manytoone, is(one2one=0), "many-to-one"]];
tac1: first(mcq_correct(ta1));
